# Rebuilt 2026-09-14 against tuned225 matrix; source: /home/gaga/huzhan/MSI_ALL_aligned_11samples_consensus0.1Da/spatial_metabolite_modules_10samples/5A_step3_module_detection.R
# 5A Step 3: MSI-only consensus network module detection
local({
suppressPackageStartupMessages({library(data.table);library(WGCNA);library(dynamicTreeCut);library(ggplot2)})
BASE<-'/home/gaga/huzhan/MSI_ALL_aligned_10samples_consensus_tuned225';OUT<-file.path(BASE,'spatial_metabolite_modules_10samples_tuned225');S3<-file.path(OUT,'step3_modules');dir.create(S3,recursive=TRUE,showWarnings=FALSE)
cs<-readRDS(file.path(OUT,'step2_spatial_consensus','spatial_consensus_and_ion_families.rds'));reps<-fread(file.path(OUT,'step2_spatial_consensus','representative_features_for_module_detection.csv'));rp<-match(reps$feature_index,cs$feature_index);stopifnot(!anyNA(rp));R<-cs$median_spearman[rp,rp];P<-cs$positive_fraction[rp,rp];N<-cs$n_evaluable_samples[rp,rp];rownames(R)<-colnames(R)<-as.character(reps$feature_index)
A<-pmax(R,0)^4;A[P<.70|N<8|!is.finite(A)]<-0;diag(A)<-1
cat('STEP3_TOM_START features',nrow(A),'nonzero_edges',sum(A[upper.tri(A)]>0),'\n');TOM<-WGCNA::TOMsimilarity(A,TOMType='signed',TOMDenom='min',suppressTOMForZeroAdjacencies=FALSE,verbose=1);diss<-1-TOM;diag(diss)<-0;hc<-hclust(as.dist(diss),method='average')
raw<-dynamicTreeCut::cutreeDynamic(dendro=hc,distM=diss,deepSplit=2,minClusterSize=5,pamRespectsDendro=FALSE,verbose=0)
size0<-sort(table(raw[raw>0]),decreasing=TRUE);ren<-setNames(sprintf('M%02d',seq_along(size0)),names(size0));module<-ifelse(raw==0,'grey',unname(ren[as.character(raw)]));reps[,module:=module]
# Sensitivity to tree cut depth on the same frozen network.
altparts<-list();for(ds in c(1,3,4)){r0<-dynamicTreeCut::cutreeDynamic(dendro=hc,distM=diss,deepSplit=ds,minClusterSize=5,pamRespectsDendro=FALSE,verbose=0);s0<-sort(table(r0[r0>0]),decreasing=TRUE);rn<-setNames(sprintf('M%02d',seq_along(s0)),names(s0));altparts[[paste0('deepSplit',ds)]]<-ifelse(r0==0,'grey',unname(rn[as.character(r0)]))}
module_ids<-setdiff(unique(module),'grey');metrics<-rbindlist(lapply(module_ids,function(md){ii<-which(module==md);subR<-R[ii,ii,drop=FALSE];subA<-A[ii,ii,drop=FALSE];conn<-rowSums(subA)-1;hub<-ii[which.max(conn)];data.table(module=md,n_representative_features=length(ii),median_within_consensus_rho=if(length(ii)>1)median(subR[upper.tri(subR)],na.rm=TRUE)else NA_real_,q25_within_consensus_rho=if(length(ii)>1)quantile(subR[upper.tri(subR)],.25,na.rm=TRUE)else NA_real_,edge_fraction_rho_ge_0.3=if(length(ii)>1)mean(subR[upper.tri(subR)]>=.3,na.rm=TRUE)else NA_real_,hub_feature_index=reps$feature_index[hub],hub_mz=reps$mz[hub],hub_weighted_connectivity=max(conn))}));setorder(metrics,module)
# Per-module robustness: best feature-set Jaccard against alternate tree depths.
stab<-rbindlist(lapply(module_ids,function(md){a<-which(module==md);rbindlist(lapply(names(altparts),function(nm){bpart<-altparts[[nm]];labs<-setdiff(unique(bpart),'grey');js<-vapply(labs,function(lb){b<-which(bpart==lb);length(intersect(a,b))/length(union(a,b))},numeric(1));data.table(module=md,sensitivity=nm,best_jaccard=if(length(js))max(js)else 0,best_matching_module=if(length(js))labs[which.max(js)]else NA_character_)}))}));stab_sum<-stab[,.(min_alt_cut_jaccard=min(best_jaccard),median_alt_cut_jaccard=median(best_jaccard)),by=module];metrics<-merge(metrics,stab_sum,by='module',all.x=TRUE)
# Membership and ion-family expansion.
fwrite(reps,file.path(S3,'representative_feature_module_membership.csv'));map<-fread(file.path(OUT,'step2_spatial_consensus','ion_family_collapse_map.csv'));map<-merge(map,reps[,.(representative_feature=feature_index,module)],by='representative_feature',all.x=TRUE);fwrite(map,file.path(S3,'all_eligible_features_module_membership_with_ion_families.csv'));fwrite(metrics,file.path(S3,'module_summary.csv'));fwrite(stab,file.path(S3,'tree_cut_sensitivity.csv'))
ord<-order(module,hc$order);pdf(file.path(S3,'step3_module_dendrogram_and_heatmap.pdf'),width=12,height=9);par(mfrow=c(2,1),mar=c(1,4,3,1));plot(hc,labels=FALSE,hang=-1,main=paste0('MSI-only consensus modules (',length(module_ids),' modules; grey=',sum(module=='grey'),')'),xlab='',sub='');cols<-c(setNames(grDevices::hcl.colors(length(module_ids),'Dynamic'),module_ids),grey='grey75');plot(seq_along(module),rep(1,length(module)),col=cols[module[hc$order]],pch=15,cex=.65,axes=FALSE,xlab='',ylab='');par(mar=c(4,4,2,2));image(seq_along(ord),seq_along(ord),pmax(R[ord,ord],0),col=hcl.colors(100,'YlOrRd',rev=TRUE),axes=FALSE,xlab='Features ordered by module',ylab='Features ordered by module',main='Positive median spatial correlation');box();dev.off()
saveRDS(list(representatives=reps,module_summary=metrics,adjacency=A,TOM=TOM,dissimilarity=diss,hclust=hc,primary_module=module,alternative_partitions=altparts,parameters=list(adjacency='max(median Spearman,0)^4; zero unless positive fraction>=0.70 and evaluable samples>=8',tree='average linkage on 1-TOM',cut='dynamicTreeCut deepSplit=2, minModuleSize=5',domain_labels_used=FALSE,LCMS_used=FALSE),session_info=sessionInfo()),file.path(S3,'MSI_consensus_modules.rds'))
writeLines(c('Modules are discovered from MSI only after conservative ion-family collapse.','Edges require recurrent positive direction and at least 8 evaluable physical samples; adjacency is based on the median sample-level Spearman correlation, not pooled pixels.','The primary module partition is dynamic tree cutting of signed TOM with no fixed module count.','Old domains and LC-MS/MS are not read. They will be used only after module discovery is frozen.'),file.path(S3,'README.txt'))
cat('STEP3_COMPLETE modules',length(module_ids),'grey',sum(module=='grey'),'\n');print(metrics);cat('OUT=',S3,'\n');gc()
})
